/* HEXA BATTLEGROUNDS upgrade — PART 9 OF 38. Only for databases that already ran setup part-01…; Run in order. Safe to re-run. */ create or replace function _arrive(p_team uuid) returns void language plpgsql as $$ declare t teams; a arenas; v_from locations; v_to locations; v_count int; begin select * into t from teams where id = p_team for update; if t.state <> 'traveling' then return; end if; select * into a from arenas where id = t.arena_id; select * into v_from from locations where id = t.travel_from; select * into v_to from locations where id = t.travel_to; update teams set state = 'idle', location_id = travel_to, travel_to = null, travel_from = null, travel_arrive_at = null, travel_started_at = null, travel_fx = null, travel_fy = null, dropped = true, visit_missions = 0 where id = p_team; if a.zone_next_at is not null and a.zone_stage < 5 and t.travel_fx is not null and not _in_circle(_zone_circle(a.event_id, a.zone_stage + 1), t.travel_fx, t.travel_fy) and _in_circle(_zone_circle(a.event_id, a.zone_stage + 1), v_to.x, v_to.y) then perform _apply(p_team, 'relocation', _cfg(a.event_id, 'pts_relocation'), 0, 0, 0, 'reloc-' || (a.zone_stage + 1), 'Reached safety before the zone collapsed'); end if; if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.arrived', jsonb_build_object('team', t.number, 'location', v_to.id)); end if; select count(*) into v_count from teams where arena_id = t.arena_id and location_id = v_to.id and id <> t.id and ready; if v_count > 0 then perform _feed(t.arena_id, 'encounter.detected', jsonb_build_object('location', v_to.id, 'squads', v_count + 1)); perform _ping('arena-' || t.arena_id::text, 'encounter'); end if; if a.phase = 'play' and not exists (select 1 from mission_instances where team_id = p_team and status = 'active' and kind <> 'battle') then perform _start_location_mission(p_team); end if; perform _ping_team(p_team, 'arrived'); end $$; create or replace function _spawn_airdrop(p_arena uuid, p_location text, p_tier text) returns uuid language plpgsql as $$ declare a arenas; v_loc text := p_location; v_tpl text; v_id uuid; v_tier text := coalesce(p_tier, 'common'); begin select * into a from arenas where id = p_arena; if v_loc is null then select id into v_loc from locations where enabled and kind <> 'start' and id <> 'tr14' and _in_circle(_zone_circle(a.event_id, least(5, a.zone_stage + 1)), x, y) order by (tags && array['airdrop', 'public']) desc, random() limit 1; if v_loc is null then v_loc := 'tr14'; end if; end if; select id into v_tpl from mission_templates where kind = 'airdrop' and status = 'published' and id not in (select template_id from airdrops where arena_id = p_arena) order by random() limit 1; if v_tpl is null then select id into v_tpl from mission_templates where kind = 'airdrop' and status = 'published' order by random() limit 1; end if; if v_tpl is null then raise exception 'NO_AIRDROP_TEMPLATE'; end if; insert into airdrops(arena_id, location_id, tier, template_id, expires_at) values (p_arena, v_loc, v_tier, v_tpl, now() + _secs(_cfg(a.event_id, 'airdrop_window'))) returning id into v_id; update arenas set last_airdrop_at = now() where id = p_arena; perform _feed(p_arena, 'airdrop.spawned', jsonb_build_object('location', v_loc, 'tier', v_tier)); return v_id; end $$; create or replace function _shift_arena(p_arena uuid, p_delta interval) returns void language plpgsql as $$ begin update arenas set shuttle_departed_at = shuttle_departed_at + p_delta, shuttle_arrive_at = shuttle_arrive_at + p_delta, roles_deadline = roles_deadline + p_delta, play_started_at = play_started_at + p_delta, zone_next_at = zone_next_at + p_delta, last_airdrop_at = last_airdrop_at + p_delta, phase_started_at = phase_started_at + p_delta, phase_next_at = phase_next_at + p_delta, red_at = red_at + p_delta, last_red_at = last_red_at + p_delta, overlay = case when overlay ? 'match' then jsonb_set(overlay, '{match,next_at}', coalesce(to_jsonb((overlay #>> '{match,next_at}')::timestamptz + p_delta), 'null'::jsonb)) else overlay end where id = p_arena; update mission_instances set deadline = deadline + p_delta, fallback_at = fallback_at + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update battles set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update sync_rounds set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update airdrops set expires_at = expires_at + p_delta, spawned_at = spawned_at + p_delta where arena_id = p_arena and status = 'open'; update alliances set expires_at = expires_at + p_delta, created_at = created_at + p_delta where arena_id = p_arena and status in ('proposed', 'active'); update story_events set expires_at = expires_at + p_delta where arena_id = p_arena and expires_at > now(); update teams set zone_hit_at = zone_hit_at + p_delta, travel_started_at = travel_started_at + p_delta, travel_arrive_at = travel_arrive_at + p_delta, recovery_deadline = recovery_deadline + p_delta, attack_cooldown_until = attack_cooldown_until + p_delta, protected_until = protected_until + p_delta, jammed_until = jammed_until + p_delta, scan_until = scan_until + p_delta where arena_id = p_arena; perform _zone_publish(p_arena); end $$;
